{"command":"cat > /tmp/pty_keys.py <<'PY'
import pty, os, select, time, sys
key=bytes.fromhex(sys.argv[1]) if sys.argv[1]!='NONE' else b''
extra_wait=float(sys.argv[2]) if len(sys.argv)>2 else 1
os.chdir('/tmp/t/work'); os.environ.update(HOME='/tmp/t/home',TERM='xterm-256color',GIT_CONFIG_NOSYSTEM='1')
pid, fd = pty.fork()
if pid==0:
    os.execv('/workspace/executable',['executable','--no-update'])
else:
    data=b''; sent=False; status=None; start=time.time()
    while time.time()-start<6:
        r,_,_=select.select([fd],[],[],0.1)
        if r:
            try: chunk=os.read(fd,4096)
            except OSError: chunk=b''
            if chunk:
                data+=chunk
                if (not sent) and b'Confirm?' in data:
                    time.sleep(0.05)
                    if key: os.write(fd,key)
                    sent=True
        w,s=os.waitpid(pid,os.WNOHANG)
        if w:
            status=s; break
    if status is None:
        print('TIMEOUT killing'); os.kill(pid,9); os.waitpid(pid,0)
    else:
        print('RAWSTATUS',status,'exit',os.waitstatus_to_exitcode(status))
    print('DATA',repr(data))
PY
cd /tmp/t/work && git branch --list feat
for name_hex in '79:lower-y' '59:upper-Y' '6e:lower-n' '4e:upper-N' '0a:LF' '0d:CR' '20:space' '09:tab' '1b:esc' '03:ctrlc' '04:ctrld' '7a:z' '31:one' '06e:invalid?' ; do hex=${name_hex%%:*}; label=${name_hex#*:}; echo "=== $label ($hex)"; timeout 10 python3 /tmp/pty_keys.py $hex; echo "branches: $(git branch --format='%(refname:short)' | tr '\n' ',') remote:$(git -C /tmp/t/remote.git branch --format='%(refname:short)' | tr '\n' ',')"; # if feat deleted recreate scenario not possible easily after y; break conditions checked manually
