use git2::{Repository, BranchType};
fn main(){
 let path=std::env::args().nth(1).unwrap();
 let repo=Repository::open(&path).unwrap();
 println!("workdir {:?}", repo.workdir());
 println!("remotes {:?}", repo.remotes().unwrap().iter().collect::<Vec<_>>());
 for t in [BranchType::Local, BranchType::Remote] {
   println!("type {:?}",t);
   for b in repo.branches(Some(t)).unwrap() {
     let (br,bt)=b.unwrap();
     println!("  name={:?} ref={:?} bt={:?} upstream_name={:?} upstream={:?}", br.get().shorthand(), br.get().name(), bt, br.upstream_name().map(|x| String::from_utf8_lossy(x.as_ref()).to_string()), br.upstream().map(|u| u.get().name().map(|s|s.to_string())));
   }
 }
 println!("refs");
 for r in repo.references().unwrap() { let r=r.unwrap(); println!("  {:?} -> {:?}", r.name(), r.symbolic_target()); }
 println!("refs glob remotes");
 for r in repo.references_glob("refs/remotes/*").unwrap() { let r=r.unwrap(); println!("  {:?} -> {:?}", r.name(), r.symbolic_target()); }
 for arg in std::env::args().skip(2) {
     match repo.resolve_reference_from_short_name(&arg) { Ok(r)=>println!("dwim {:?} => name={:?} resolved={:?} branch={} remote={}",arg,r.name(),r.resolve().unwrap().name(),r.is_branch(),r.is_remote()), Err(e)=>println!("dwim {:?} err {} code={:?} class={:?}",arg,e,e.code(),e.class()) }
 }
}
RS
