use anyhow::{bail, Result};
use git2::{Config, ErrorCode, Repository};
use std::fmt;
use std::str::FromStr;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Scope {
    All,
    Remote(String),
}

impl Scope {
    pub fn matches(&self, remote: &str) -> bool {
        match self {
            Scope::All => true,
            Scope::Remote(name) => name == remote,
        }
    }
}

#[derive(Debug)]
pub struct ScopeEmptyError;

impl fmt::Display for ScopeEmptyError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Scope is empty")
    }
}

impl std::error::Error for ScopeEmptyError {}

#[derive(Debug)]
pub enum DeleteRangeParseError {
    InvalidFormat(String),
    Scope(ScopeEmptyError),
}

impl fmt::Display for DeleteRangeParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DeleteRangeParseError::InvalidFormat(s) => {
                write!(f, "Invalid delete range format `{}`", s)
            }
            DeleteRangeParseError::Scope(e) => {
                write!(
                    f,
                    "Scope parse error for delete range while parsing scope: {}",
                    e
                )
            }
        }
    }
}

impl std::error::Error for DeleteRangeParseError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            DeleteRangeParseError::InvalidFormat(_) => None,
            DeleteRangeParseError::Scope(e) => Some(e),
        }
    }
}

fn parse_scope(s: &str) -> std::result::Result<Scope, DeleteRangeParseError> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        Err(DeleteRangeParseError::Scope(ScopeEmptyError))
    } else if trimmed == "*" {
        Ok(Scope::All)
    } else {
        Ok(Scope::Remote(trimmed.to_string()))
    }
}

#[derive(Clone, Debug)]
pub enum DeleteRange {
    Merged(Scope),
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    Local,
    Remote(Scope),
}

impl FromStr for DeleteRange {
    type Err = DeleteRangeParseError;

    fn from_str(s: &str) -> std::result::Result<Self, Self::Err> {
        let mut parts = s.splitn(2, ':');
        let kind = parts.next().unwrap_or("").trim();
        let scope = parts.next();
        match (kind, scope) {
            ("merged", Some(scope)) => Ok(DeleteRange::Merged(parse_scope(scope)?)),
            ("merged-remote", Some(scope)) => {
                Ok(DeleteRange::MergedRemote(parse_scope(scope)?))
            }
            ("diverged", Some(scope)) => Ok(DeleteRange::Diverged(parse_scope(scope)?)),
            ("remote", Some(scope)) => Ok(DeleteRange::Remote(parse_scope(scope)?)),
            ("merged-local", None) => Ok(DeleteRange::MergedLocal),
            ("stray", None) => Ok(DeleteRange::Stray),
            ("local", None) => Ok(DeleteRange::Local),
            _ => Err(DeleteRangeParseError::InvalidFormat(s.to_string())),
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct DeleteRanges {
    pub merged_local: bool,
    pub merged_remote: Vec<Scope>,
    pub stray: bool,
    pub diverged: Vec<Scope>,
    pub local: bool,
    pub remote: Vec<Scope>,
}

impl DeleteRanges {
    pub fn from_delete_ranges(ranges: &[DeleteRange]) -> Self {
        let mut out = DeleteRanges::default();
        for range in ranges {
            match range {
                DeleteRange::Merged(scope) => {
                    out.merged_local = true;
                    out.merged_remote.push(scope.clone());
                }
                DeleteRange::MergedLocal => out.merged_local = true,
                DeleteRange::MergedRemote(scope) => {
                    out.merged_remote.push(scope.clone())
                }
                DeleteRange::Stray => out.stray = true,
                DeleteRange::Diverged(scope) => out.diverged.push(scope.clone()),
