pub struct DeleteRanges {
    pub merged_local: bool,
    pub merged_remote: Vec<Scope>,
    pub stray: bool,
    pub diverged: Vec<Scope>,
    pub local: bool,
    pub remote: Vec<Scope>,
}

impl DeleteRanges {
    pub fn from_delete_ranges(ranges: &[DeleteRange]) -> Self {
        let mut out = DeleteRanges::default();
        for range in ranges {
            match range {
                DeleteRange::Merged(scope) => {
                    out.merged_local = true;
                    out.merged_remote.push(scope.clone());
                }
                DeleteRange::MergedLocal => out.merged_local = true,
                DeleteRange::MergedRemote(scope) => {
                    out.merged_remote.push(scope.clone())
                }
                DeleteRange::Stray => out.stray = true,
                DeleteRange::Diverged(scope) => out.diverged.push(scope.clone()),
                DeleteRange::Local => out.local = true,
                DeleteRange::Remote(scope) => out.remote.push(scope.clone()),
            }
        }
        out
    }

    pub fn tracking_scanned(ranges: &[DeleteRange]) -> bool {
        ranges.iter().any(|range| {
            matches!(
                range,
                DeleteRange::Merged(_)
                    | DeleteRange::MergedLocal
                    | DeleteRange::MergedRemote(_)
                    | DeleteRange::Stray
                    | DeleteRange::Diverged(_)
            )
        })
    }

    pub fn merged_remote_matches(&self, remote: &str) -> bool {
        self.merged_remote.iter().any(|scope| scope.matches(remote))
    }

    pub fn diverged_matches(&self, remote: &str) -> bool {
        self.diverged.iter().any(|scope| scope.matches(remote))
    }

    pub fn remote_matches(&self, remote: &str) -> bool {
        self.remote.iter().any(|scope| scope.matches(remote))
    }
}

