fn config_list(config: &Config, key: &str) -> Result<Option<Vec<String>>> {
    let mut entries = config.multivar(key, None)?;
    let mut found = false;
    let mut values = Vec::new();
    while let Some(entry) = entries.next() {
        let entry = entry?;
        found = true;
        let value = entry.value()?;
        values.extend(
            value
                .split(',')
                .filter(|token| !token.is_empty())
                .map(|token| token.to_string()),
        );
    }
    Ok(if found { Some(values) } else { None })
}

fn default_base_targets(repo: &Repository) -> Vec<String> {
    let mut targets = Vec::new();
    if let Ok(mut references) = repo.references_glob("refs/remotes/*/HEAD") {
        while let Some(reference) = references.next() {
            let Ok(reference) = reference else {
                continue;
            };
            if let Ok(resolved) = reference.resolve() {
                if let Ok(Some(name)) = resolved.name() {
                    let name = name.to_string();
                    if !targets.contains(&name) {
                        targets.push(name);
                    }
                }
            }
        }
    }
    targets
}

