fn resolve_bool(
    positive: bool,
    negative: bool,
    positive_name: &str,
    negative_name: &str,
    config: &Config,
    key: &str,
) -> Result<bool> {
    if positive && negative {
        eprintln!(
            "Error: Flag '{}' and '{}' cannot be used simultaneously",
            positive_name, negative_name
        );
        std::process::exit(-1);
    }
    if positive {
        return Ok(true);
    }
    if negative {
        return Ok(false);
    }
    match config.get_bool(key) {
        Ok(value) => Ok(value),
        Err(e) if e.code() == ErrorCode::NotFound => Ok(true),
        Err(e) => Err(e.into()),
    }
}

pub fn resolve_config(repo: &Repository, cli: CliOptions) -> Result<ResolvedConfig> {
    let config = repo.config()?;

    let bases_config = if cli.bases.is_none() {
        config_list(&config, "trim.bases")?
    } else {
        None
    };

    let protected = if let Some(protected) = cli.protected {
        protected
    } else if let Some(protected) = config_list(&config, "trim.protected")? {
        protected
    } else {
        Vec::new()
    };

    let update = resolve_bool(
        cli.update,
        cli.no_update,
        "update",
        "no-update",
        &config,
        "trim.update",
    )?;

    let update_interval = if let Some(value) = cli.update_interval {
        value
    } else {
        match config.get_i64("trim.updateInterval") {
            Ok(value) => {
                assert!(
                    value >= 0,
                    "`git config trim.updateInterval` cannot be negative value"
                );
                value as u64
            }
            Err(e) if e.code() == ErrorCode::NotFound => 5,
            Err(e) => return Err(e.into()),
        }
    };

    let confirm = resolve_bool(
        cli.confirm,
        cli.no_confirm,
        "confirm",
        "no-confirm",
        &config,
        "trim.confirm",
    )?;

    let detach = resolve_bool(
        cli.detach,
        cli.no_detach,
        "detach",
        "no-detach",
        &config,
        "trim.detach",
    )?;

    let delete_ranges_raw = if let Some(delete) = cli.delete {
        delete
    } else if let Some(tokens) = config_list(&config, "trim.delete")? {
        let mut parsed = Vec::new();
        for token in tokens {
            parsed.push(token.parse::<DeleteRange>()?);
        }
        parsed
    } else {
        vec!["merged:origin".parse::<DeleteRange>().unwrap()]
    };
    let tracking_scanned = DeleteRanges::tracking_scanned(&delete_ranges_raw);
    let delete_ranges = DeleteRanges::from_delete_ranges(&delete_ranges_raw);

    let bases_input = if let Some(bases) = cli.bases {
        BasesInput::Explicit(bases)
    } else if let Some(bases) = bases_config {
        if bases.is_empty() {
            eprintln!(
                "I found that `git config trim.bases` is empty! Try any following commands to set valid bases:"
            );
            eprintln!(" * `git config trim.bases develop,master` for a repository.");
            eprintln!(
                " * `git config --global trim.bases develop,master` to set globally."
            );
            eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            bail!("No base branch is found!");
        }
        BasesInput::Explicit(bases)
    } else {
        if default_base_targets(repo).is_empty() {
            print_no_base_error(repo);
            bail!("No base branch is found!");
        }
        BasesInput::Default
    };

    Ok(ResolvedConfig {
        protected,
        update,
        update_interval,
        confirm,
        detach,
        delete_ranges_raw,
        delete_ranges,
        tracking_scanned,
        bases_input,
    })
}
