}

fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

fn collect_locals(repo: &Repository) -> Result<Vec<LocalInfo>> {
    let config = repo.config()?;
    let mut locals = Vec::new();
    for branch in repo.branches(Some(BranchType::Local))? {
        let (branch, _) = branch?;
        let reference = branch.get();
        let refname = lossy(reference.name_bytes());
        let shorthand = lossy(reference.shorthand_bytes());
        let upstream_refname = repo
            .branch_upstream_name(&refname)
            .ok()
            .and_then(|buf| buf.as_str().ok().map(|s| s.to_string()));
        let (upstream_remote_name, upstream_merge_ref) = if upstream_refname.is_some() {
            (
                config
                    .get_string(&format!("branch.{}.remote", shorthand))
                    .ok(),
                config
                    .get_string(&format!("branch.{}.merge", shorthand))
                    .ok(),
            )
        } else {
            (None, None)
        };
        locals.push(LocalInfo {
            shorthand,
            refname,
            upstream_refname,
            upstream_remote_name,
            upstream_merge_ref,
        });
    }
    Ok(locals)
}

fn remote_merge_ref(repo: &Repository, remote_name: &str, remote_ref: &str) -> String {
    if let Ok(remote) = repo.find_remote(remote_name) {
        for refspec in remote.refspecs() {
            if refspec.direction() == git2::Direction::Fetch {
                if let Ok(transformed) = refspec.rtransform(remote_ref) {
                    if let Ok(transformed) = transformed.as_str() {
                        return transformed.to_string();
                    }
                }
            }
        }
    }
    let suffix = remote_ref
        .strip_prefix("refs/remotes/")
        .unwrap_or(remote_ref);
    let branch_path = suffix
        .split_once('/')
        .map(|(_, rest)| rest)
        .unwrap_or(suffix);
    format!("refs/heads/{}", branch_path)
}

fn collect_remotes(repo: &Repository) -> Result<Vec<RemoteInfo>> {
    let mut remotes = Vec::new();
    for branch in repo.branches(Some(BranchType::Remote))? {
        let (branch, _) = branch?;
        let reference = branch.get();
        if reference
            .symbolic_target()
            .map(|target| target.is_some())
            .unwrap_or(false)
        {
            continue;
        }
        let refname = lossy(reference.name_bytes());
        let shorthand = lossy(reference.shorthand_bytes());
        let remote_name = match repo.branch_remote_name(&refname) {
            Ok(buf) => buf.as_str()?.to_string(),
            Err(_) => bail!("remote with matching refspec not found"),
        };
        let merge_ref = remote_merge_ref(repo, &remote_name, &refname);
        remotes.push(RemoteInfo {
            shorthand,
            refname,
            remote_name,
            merge_ref,
        });
    }
    Ok(remotes)
}

fn parse_worktrees(workdir: &Path) -> Result<HashMap<String, String>> {
    let output = run_git_capture(workdir, &["worktree", "list", "--porcelain"])?;
    let mut map = HashMap::new();
    let mut current_path: Option<String> = None;
    for line in output.lines() {
        if line.is_empty() {
            current_path = None;
        } else if let Some(path) = line.strip_prefix("worktree ") {
            current_path = Some(path.to_string());
        } else if let Some(branch) = line.strip_prefix("branch ") {
            if let Some(path) = &current_path {
                map.insert(branch.to_string(), path.clone());
            }
        }
    }
    Ok(map)
}

struct MergedChecker<'repo> {
    repo: &'repo Repository,
    commit_patchids: HashMap<Oid, Option<Oid>>,
    base_patchid_sets: HashMap<(Oid, Oid), HashSet<Oid>>,
    merged_cache: HashMap<String, bool>,
}

impl<'repo> MergedChecker<'repo> {
    fn new(repo: &'repo Repository) -> Self {
        Self {
            repo,
            commit_patchids: HashMap::new(),
            base_patchid_sets: HashMap::new(),
            merged_cache: HashMap::new(),
        }
    }

    fn commit_for_ref(&self, refname: &str) -> Result<Commit<'repo>> {
        let commit = self.repo.find_reference(refname)?.peel_to_commit()?;
        Ok(commit)
    }

    fn commit_patchid(&mut self, oid: Oid) -> Result<Option<Oid>> {
        if let Some(cached) = self.commit_patchids.get(&oid) {
            return Ok(*cached);
        }
        let commit = self.repo.find_commit(oid)?;
        let patchid = if commit.parent_count() != 1 {
            None
        } else {
            let parent = commit.parent(0)?;
            let parent_tree = parent.tree()?;
            let commit_tree = commit.tree()?;
            let diff =
                self.repo
                    .diff_tree_to_tree(Some(&parent_tree), Some(&commit_tree), None)?;
            Some(diff.patchid(None)?)
        };
        self.commit_patchids.insert(oid, patchid);
        Ok(patchid)
    }

    fn patchids_between(&mut self, tip: Oid, hide: Oid) -> Result<Vec<Oid>> {
        let mut walk = self.repo.revwalk()?;
        walk.push(tip)?;
        walk.hide(hide)?;
        let mut patchids = Vec::new();
        for oid in walk {
            let oid = oid?;
            if let Some(patchid) = self.commit_patchid(oid)? {
                patchids.push(patchid);
            }
        }
        Ok(patchids)
    }

    fn patchid_set_between(&mut self, tip: Oid, hide: Oid) -> Result<HashSet<Oid>> {
        if let Some(cached) = self.base_patchid_sets.get(&(tip, hide)) {
            return Ok(cached.clone());
        }
        let set: HashSet<Oid> = self.patchids_between(tip, hide)?.into_iter().collect();
        self.base_patchid_sets.insert((tip, hide), set.clone());
        Ok(set)
    }

    fn is_merged_to_base(&mut self, branch_ref: &str, base_ref: &str) -> Result<bool> {
        let branch_commit = self.commit_for_ref(branch_ref)?;
        let base_commit = self.commit_for_ref(base_ref)?;
        if branch_commit.id() == base_commit.id() {
            return Ok(true);
        }
        let merge_base = match self.repo.merge_base(base_commit.id(), branch_commit.id()) {
            Ok(oid) => oid,
            Err(e) if e.code() == ErrorCode::NotFound => return Ok(false),
            Err(e) => return Err(e.into()),
        };
        if merge_base == branch_commit.id() {
            return Ok(true);
        }
        let branch_patchids = self.patchids_between(branch_commit.id(), merge_base)?;
        let base_patchids = self.patchid_set_between(base_commit.id(), merge_base)?;
        if branch_patchids
            .iter()
            .all(|patchid| base_patchids.contains(patchid))
        {
            return Ok(true);
        }
        let merge_base_commit = self.repo.find_commit(merge_base)?;
        let merge_base_tree = merge_base_commit.tree()?;
        let branch_tree = branch_commit.tree()?;
        let diff =
            self.repo
                .diff_tree_to_tree(Some(&merge_base_tree), Some(&branch_tree), None)?;
        let squash_patchid = diff.patchid(None)?;
        Ok(base_patchids.contains(&squash_patchid))
    }

    fn is_merged_any(&mut self, branch_ref: &str, base_refs: &[String]) -> Result<bool> {
        // The cache key intentionally does not include the base list: the
        // list is fixed for one invocation of the program.
        if let Some(cached) = self.merged_cache.get(branch_ref) {
            return Ok(*cached);
        }
        let mut merged = false;
        for base_ref in base_refs {
            if self.is_merged_to_base(branch_ref, base_ref)? {
                merged = true;
                break;
            }
        }
        self.merged_cache.insert(branch_ref.to_string(), merged);
        Ok(merged)
    }
}

#[derive(Clone, Debug)]
enum Reason {
    Protected(String),
    Base,
    Head,
    Worktree(String),
    Range(String),
}

impl Reason {
    fn priority(&self) -> u8 {
        match self {
            Reason::Protected(_) => 5,
            Reason::Base => 4,
            Reason::Worktree(_) => 3,
            Reason::Range(_) => 2,
            Reason::Head => 1,
        }
    }
}

#[derive(Clone, Debug)]
enum Annotation {
    Skipped(u8),
    Base,
    TracksBase(String),
    Note { prefix: String, reason: Reason },
}

impl Annotation {
    fn suffix(&self) -> String {
        match self {
            Annotation::Skipped(number) => format!(" *{}", number),
            Annotation::Base => " [base]".to_string(),
            Annotation::TracksBase(token) => format!(" [tracks base `{}`]", token),
            Annotation::Note { prefix, reason } => {
                let reason = match reason {
                    Reason::Protected(pattern) => {
                        format!("protected by a pattern `{}`", pattern)
                    }
                    Reason::Base => "base".to_string(),
                    Reason::Head => "HEAD".to_string(),
                    Reason::Worktree(path) => format!("worktree at {}", path),
                    Reason::Range(range) => {
                        format!("delete range `{}` was not given", range)
                    }
                };
                format!(" [{}, but: {}]", prefix, reason)
            }
        }
    }

    fn reason_priority(&self) -> u8 {
        match self {
            Annotation::Note { reason, .. } => reason.priority(),
            _ => 0,
        }
    }
}

fn first_protected_pattern<'a>(
    patterns: &'a [String],
    candidates: &[String],
) -> Option<String> {
    for pattern in patterns {
        if let Ok(glob_pattern) = glob::Pattern::new(pattern) {
            if candidates
                .iter()
                .any(|candidate| glob_pattern.matches(candidate))
            {
                return Some(pattern.clone());
            }
        }
    }
    None
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum RemoteSideId {
    Actual(usize),
    Pseudo(usize),
}

#[derive(Clone)]
enum LocalOutcome {
    Remain(Option<Annotation>),
    DeleteMerged,
    DeleteStray,
}

#[derive(Clone)]
enum RemoteOutcome {
    Remain(Option<Annotation>),
    DeleteMerged { non_upstream: bool },
}

struct DivergedRemoteItem {
    remote_name: String,
    merge_ref: String,
    side: RemoteSideId,
}

#[derive(Debug)]
struct PromptIoError {
    source: io::Error,
}

impl std::fmt::Display for PromptIoError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "IO error: {}", self.source)
    }
}

impl std::error::Error for PromptIoError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}

fn prompt_io<T>(result: io::Result<T>) -> Result<T> {
    result.map_err(|source| anyhow!(PromptIoError { source }))
}

fn read_single_key(file: &std::fs::File) -> io::Result<u8> {
    let fd = file.as_raw_fd();
    unsafe {
        let mut original: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(fd, &mut original) != 0 {
            return Err(io::Error::last_os_error());
        }
        let mut raw = original;
        raw.c_lflag &= !(libc::ICANON | libc::ECHO);
        raw.c_cc[libc::VMIN] = 1;
        raw.c_cc[libc::VTIME] = 0;
        if libc::tcsetattr(fd, libc::TCSANOW, &raw) != 0 {
            return Err(io::Error::last_os_error());
        }
        let mut buffer = [0u8; 1];
        let result = (&*file).read_exact(&mut buffer);
        let _ = libc::tcsetattr(fd, libc::TCSANOW, &original);
        result?;
        Ok(buffer[0])
    }
}

fn prompt_confirm() -> Result<bool> {
    if unsafe { libc::isatty(libc::STDERR_FILENO) } != 1 {
        return Err(anyhow!(PromptIoError {
            source: io::Error::new(io::ErrorKind::Other, "not a terminal"),
        }));
    }
    prompt_io(write!(io::stderr(), "Confirm? [y/N] "))?;
    prompt_io(write!(io::stderr(), "\x1b[?25l"))?;
    prompt_io(io::stderr().flush())?;

    let tty = prompt_io(std::fs::File::open("/dev/tty"))?;
    let answer = loop {
        match prompt_io(read_single_key(&tty))? {
            b'y' | b'Y' => break true,
            b'n' | b'N' | b'\n' | b'\r' => break false,
            _ => continue,
        }
    };

    prompt_io(write!(
        io::stderr(),
        "\r\x1b[2KConfirm? {}\n",
        if answer { "yes" } else { "no" }
    ))?;
    prompt_io(write!(io::stderr(), "\x1b[?25h"))?;
    prompt_io(io::stderr().flush())?;
    Ok(answer)
}

fn check_remote_heads(repo: &Repository, workdir: &Path) -> Result<()> {
    let remote_names_array = repo.remotes()?;
    let remote_names: Vec<String> = remote_names_array
        .iter()
        .filter_map(|name| name.ok().flatten().map(|name| name.to_string()))
        .collect();
    let mut out_of_sync: Vec<(String, String, String)> = Vec::new();

    for remote_name in &remote_names {
        let local_head_name = format!("refs/remotes/{}/HEAD", remote_name);
        let Ok(local_head) = repo.find_reference(&local_head_name) else {
            continue;
        };
        let Ok(local_resolved) = local_head.resolve() else {
            continue;
        };
        let Ok(Some(local_resolved_name)) = local_resolved.name() else {
            continue;
        };
        let local_branch_ref = remote_merge_ref(repo, remote_name, local_resolved_name);

        let output = run_git_capture(
            workdir,
            &["ls-remote", "--symref", remote_name, "HEAD"],
        )?;
        let server_ref = output.lines().find_map(|line| {
            let rest = line.strip_prefix("ref: ")?;
            rest.split_whitespace().next().map(|s| s.to_string())
        });
        let Some(server_ref) = server_ref else {
            continue;
        };
        if server_ref != local_branch_ref {
            out_of_sync.push((
                remote_name.clone(),
                local_branch_ref,
                server_ref,
            ));
        }
    }

    if !out_of_sync.is_empty() {
        eprintln!(
            "You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s."
        );
        eprintln!("However, they seems to be out of sync.");
        for (remote, local, server) in &out_of_sync {
            eprintln!(" * {}: {} -> {}", remote, local, server);
        }
        eprintln!("You can sync them with these commands:");
        for (remote, _, _) in &out_of_sync {
            eprintln!(" > git remote set-head {} --auto", remote);
        }
        eprintln!("Or you can set base branches manually:");
        eprintln!(
            " * `git config trim.bases develop,master` will set base branches for git-trim for a repository."
        );
        eprintln!(
            " * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally."
        );
        eprintln!(
            " * `git trim --bases develop,master` will temporarily set base branches for `git-trim`"
        );
    }
    Ok(())
}

fn run(cli: CliOptions) -> Result<()> {
    let dry_run = cli.dry_run;
    let repo = Repository::open_from_env()?;
    if repo.remotes()?.is_empty() {
        bail!("git-trim requires at least one remote");
    }

    let resolved = config::resolve_config(&repo, cli)?;
    let _ = resolved.update_interval;

    if repo.is_bare() {
        bail!("Bare repository is not supported");
    }
    let workdir: PathBuf = repo
        .workdir()
        .ok_or_else(|| anyhow!("Bare repository is not supported"))?
        .to_path_buf();

    if resolved.update {
        if !dry_run {
            run_git_inherit(&workdir, &["remote", "update", "--prune"])?;
        }
        println!();
    }

    let bases = canonicalize_bases(&repo, &resolved.bases_input)?;
    let has_bases = !bases.remote_ref_list.is_empty();

    let head = repo.head()?;
    let current_head_ref = if head.is_branch() {
        head.name().ok().flatten().map(|name| name.to_string())
    } else {
        None
    };

    let worktrees = parse_worktrees(&workdir)?;
    let locals = collect_locals(&repo)?;
    let remotes = collect_remotes(&repo)?;

    let actual_remote_by_ref: HashMap<String, usize> = remotes
        .iter()
        .enumerate()
        .map(|(index, remote)| (remote.refname.clone(), index))
        .collect();

    let mut pseudos: Vec<PseudoRemote> = Vec::new();
    let mut pseudo_by_ref: HashMap<String, usize> = HashMap::new();
    for local in &locals {
        let Some(upstream_refname) = &local.upstream_refname else {
            continue;
        };
        if actual_remote_by_ref.contains_key(upstream_refname)
            || pseudo_by_ref.contains_key(upstream_refname)
        {
            continue;
        }
        let Ok(reference) = repo.find_reference(upstream_refname) else {
            continue;
        };
        let remote_name = local
            .upstream_remote_name
            .clone()
            .unwrap_or_else(|| "".to_string());
        let merge_ref = local
            .upstream_merge_ref
            .clone()
            .unwrap_or_else(|| upstream_refname.clone());
        let shorthand = lossy(reference.shorthand_bytes());
        let display_name = if upstream_refname.starts_with("refs/remotes/") {
            shorthand.clone()
        } else {
            format!("{}, {}", remote_name, merge_ref)
        };
        let index = pseudos.len();
        pseudo_by_ref.insert(upstream_refname.clone(), index);
        pseudos.push(PseudoRemote {
            display_name,
            shorthand,
            refname: upstream_refname.clone(),
            remote_name,
            merge_ref,
        });
    }

    let upstream_ref_set: HashSet<String> = locals
        .iter()
        .filter_map(|local| local.upstream_refname.clone())
        .collect();

    let delete_ranges: DeleteRanges = resolved.delete_ranges.clone();
    let mut checker = MergedChecker::new(&repo);

    let mut remote_outcomes: Vec<RemoteOutcome> = Vec::new();
    for remote in &remotes {
        let is_upstream = upstream_ref_set.contains(&remote.refname);
        let outcome = if is_upstream {
            if !resolved.tracking_scanned {
                RemoteOutcome::Remain(Some(Annotation::Skipped(1)))
            } else if !has_bases {
                RemoteOutcome::Remain(None)
            } else if bases.remote_refs.contains(&remote.refname) {
                RemoteOutcome::Remain(Some(Annotation::Base))
            } else {
                let merged =
                    checker.is_merged_any(&remote.refname, &bases.remote_ref_list)?;
                if !merged {
                    RemoteOutcome::Remain(None)
                } else if let Some(pattern) = first_protected_pattern(
                    &resolved.protected,
                    &[
                        remote.shorthand.clone(),
                        remote.refname.clone(),
                    ],
                ) {
                    RemoteOutcome::Remain(Some(Annotation::Note {
                        prefix: "merged".to_string(),
                        reason: Reason::Protected(pattern),
                    }))
                } else if delete_ranges.merged_remote_matches(&remote.remote_name) {
                    RemoteOutcome::DeleteMerged {
                        non_upstream: false,
                    }
                } else {
                    RemoteOutcome::Remain(Some(Annotation::Note {
                        prefix: "merged".to_string(),
                        reason: Reason::Range(format!(
                            "merged-remote:{}",
                            remote.remote_name
                        )),
                    }))
                }
            }
        } else if !has_bases {
            RemoteOutcome::Remain(None)
        } else if !delete_ranges.remote_matches(&remote.remote_name) {
            RemoteOutcome::Remain(Some(Annotation::Skipped(3)))
        } else {
            let merged =
                checker.is_merged_any(&remote.refname, &bases.remote_ref_list)?;
            if !merged {
                RemoteOutcome::Remain(None)
            } else if bases.remote_refs.contains(&remote.refname) {
                RemoteOutcome::Remain(Some(Annotation::Note {
                    prefix: "merged non-upstream".to_string(),
                    reason: Reason::Base,
                }))
            } else if let Some(pattern) = first_protected_pattern(
                &resolved.protected,
                &[
                    remote.shorthand.clone(),
                    remote.refname.clone(),
                ],
            ) {
                RemoteOutcome::Remain(Some(Annotation::Note {
                    prefix: "merged non-upstream".to_string(),
                    reason: Reason::Protected(pattern),
                }))
            } else {
                RemoteOutcome::DeleteMerged { non_upstream: true }
            }
        };
        remote_outcomes.push(outcome);
    }

    let mut diverged_remote_items: Vec<DivergedRemoteItem> = Vec::new();
    let mut actual_diverged_annotations: HashMap<usize, Vec<Annotation>> =
        HashMap::new();
    let mut pseudo_diverged_annotations: HashMap<usize, Vec<Annotation>> =
        HashMap::new();
    let mut local_outcomes: Vec<LocalOutcome> = Vec::new();

    for local in &locals {
        let is_current = current_head_ref.as_deref() == Some(local.refname.as_str());
        let other_worktree = if is_current {
            None
        } else {
            worktrees.get(&local.refname).cloned()
        };
        let local_candidates = vec![local.shorthand.clone(), local.refname.clone()];

        let outcome = if local.upstream_refname.is_some() {
            if !resolved.tracking_scanned {
                LocalOutcome::Remain(Some(Annotation::Skipped(1)))
            } else if !has_bases {
                LocalOutcome::Remain(None)
            } else if bases.local_refs.contains(&local.refname) {
                LocalOutcome::Remain(Some(Annotation::Base))
            } else if let Some(token) = local
                .upstream_refname
                .as_ref()
                .and_then(|upstream| bases.direct_remote_tokens.get(upstream))
            {
                LocalOutcome::Remain(Some(Annotation::TracksBase(token.clone())))
            } else {
                let upstream_refname = local.upstream_refname.clone().unwrap();
                let side = if let Some(index) =
                    actual_remote_by_ref.get(&upstream_refname)
                {
                    Some(RemoteSideId::Actual(*index))
                } else if let Some(index) = pseudo_by_ref.get(&upstream_refname) {
                    Some(RemoteSideId::Pseudo(*index))
                } else {
                    None
                };
                let local_merged =
                    checker.is_merged_any(&local.refname, &bases.remote_ref_list)?;
                let remote_merged = match side {
                    Some(RemoteSideId::Actual(index)) => Some(
                        checker.is_merged_any(
                            &remotes[index].refname,
                            &bases.remote_ref_list,
                        )?,
                    ),
                    Some(RemoteSideId::Pseudo(index)) => {
                        let pseudo = &pseudos[index];
                        if pseudo.refname.starts_with("refs/remotes/") {
                            Some(checker.is_merged_any(
                                &pseudo.refname,
                                &bases.remote_ref_list,
                            )?)
                        } else {
                            Some(false)
                        }
                    }
                    None => None,
                };

                match (side, remote_merged) {
                    (_, Some(true)) if !local_merged => {
                        // Stray local branch; the remote side was handled
                        // independently when it is an actual remote branch.
                        if let Some(pattern) =
                            first_protected_pattern(&resolved.protected, &local_candidates)
                        {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Protected(pattern),
                            }))
                        } else if let Some(path) = &other_worktree {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Worktree(path.clone()),
                            }))
                        } else if !delete_ranges.stray {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Range("stray".to_string()),
                            }))
                        } else if is_current && !resolved.detach {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Head,
                            }))
                        } else {
                            LocalOutcome::DeleteStray
                        }
                    }
                    (Some(side), Some(false)) if local_merged => {
                        let (remote_name, merge_ref, remote_candidates, local_other, remote_other) =
                            match side {
                                RemoteSideId::Actual(index) => {
                                    let remote = &remotes[index];
                                    (
                                        remote.remote_name.clone(),
                                        remote.merge_ref.clone(),
                                        vec![
                                            remote.shorthand.clone(),
                                            remote.refname.clone(),
                                        ],
                                        remote.refname.clone(),
                                        local.refname.clone(),
                                    )
                                }
                                RemoteSideId::Pseudo(index) => {
                                    let pseudo = &pseudos[index];
                                    (
                                        pseudo.remote_name.clone(),
                                        pseudo.merge_ref.clone(),
                                        vec![
                                            pseudo.shorthand.clone(),
                                            pseudo.refname.clone(),
                                        ],
                                        pseudo.display_name.clone(),
                                        local.shorthand.clone(),
                                    )
                                }
                            };
                        let protected = first_protected_pattern(
                            &resolved.protected,
                            &local_candidates,
                        )
                        .or_else(|| {
                            first_protected_pattern(
                                &resolved.protected,
                                &remote_candidates,
                            )
                        });
                        let reason = if let Some(pattern) = protected {
                            Some(Reason::Protected(pattern))
                        } else if let Some(path) = &other_worktree {
                            Some(Reason::Worktree(path.clone()))
                        } else if !delete_ranges.diverged_matches(&remote_name) {
                            Some(Reason::Range(format!("diverged:{}", remote_name)))
                        } else if is_current && !resolved.detach {
                            Some(Reason::Head)
                        } else {
                            None
                        };
                        if let Some(reason) = reason {
                            let local_annotation = Annotation::Note {
                                prefix: format!("diverged with {}", local_other),
                                reason: reason.clone(),
                            };
                            let remote_annotation = Annotation::Note {
                                prefix: format!("diverged with {}", remote_other),
                                reason,
                            };
                            match side {
                                RemoteSideId::Actual(index) => {
                                    actual_diverged_annotations
                                        .entry(index)
                                        .or_default()
                                        .push(remote_annotation);
                                }
                                RemoteSideId::Pseudo(index) => {
                                    pseudo_diverged_annotations
                                        .entry(index)
                                        .or_default()
                                        .push(remote_annotation);
                                }
                            }
                            LocalOutcome::Remain(Some(local_annotation))
                        } else {
                            diverged_remote_items.push(DivergedRemoteItem {
                                remote_name,
                                merge_ref,
                                side,
                            });
                            LocalOutcome::DeleteMerged
                        }
                    }
                    (None, None) if !local_merged => {
                        if let Some(pattern) =
                            first_protected_pattern(&resolved.protected, &local_candidates)
                        {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Protected(pattern),
                            }))
                        } else if let Some(path) = &other_worktree {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Worktree(path.clone()),
                            }))
                        } else if !delete_ranges.stray {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Range("stray".to_string()),
                            }))
                        } else if is_current && !resolved.detach {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "stray".to_string(),
                                reason: Reason::Head,
                            }))
                        } else {
                            LocalOutcome::DeleteStray
                        }
                    }
                    _ if local_merged => {
                        if let Some(pattern) =
                            first_protected_pattern(&resolved.protected, &local_candidates)
                        {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "merged".to_string(),
                                reason: Reason::Protected(pattern),
                            }))
                        } else if let Some(path) = &other_worktree {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "merged".to_string(),
                                reason: Reason::Worktree(path.clone()),
                            }))
                        } else if !delete_ranges.merged_local {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "merged".to_string(),
                                reason: Reason::Range("merged-local".to_string()),
                            }))
                        } else if is_current && !resolved.detach {
                            LocalOutcome::Remain(Some(Annotation::Note {
                                prefix: "merged".to_string(),
                                reason: Reason::Head,
                            }))
                        } else {
                            LocalOutcome::DeleteMerged
                        }
                    }
                    _ => LocalOutcome::Remain(None),
                }
            }
        } else if !delete_ranges.local {
            LocalOutcome::Remain(Some(Annotation::Skipped(2)))
        } else if !has_bases {
            LocalOutcome::Remain(None)
        } else {
            let merged =
                checker.is_merged_any(&local.refname, &bases.remote_ref_list)?;
            if !merged {
                LocalOutcome::Remain(None)
            } else if let Some(pattern) =
                first_protected_pattern(&resolved.protected, &local_candidates)
            {
                LocalOutcome::Remain(Some(Annotation::Note {
                    prefix: "merged non-tracking".to_string(),
                    reason: Reason::Protected(pattern),
                }))
            } else if let Some(path) = &other_worktree {
                LocalOutcome::Remain(Some(Annotation::Note {
                    prefix: "merged non-tracking".to_string(),
                    reason: Reason::Worktree(path.clone()),
                }))
            } else if is_current && !resolved.detach {
                LocalOutcome::Remain(Some(Annotation::Note {
                    prefix: "merged non-tracking".to_string(),
                    reason: Reason::Head,
                }))
            } else {
                LocalOutcome::DeleteMerged
            }
        };
        local_outcomes.push(outcome);
    }

    let diverged_actual_deleted: HashSet<usize> = diverged_remote_items
        .iter()
        .filter_map(|item| match item.side {
            RemoteSideId::Actual(index) => Some(index),
            RemoteSideId::Pseudo(_) => None,
        })
        .collect();
    let diverged_pseudo_deleted: HashSet<usize> = diverged_remote_items
        .iter()
        .filter_map(|item| match item.side {
            RemoteSideId::Pseudo(index) => Some(index),
            RemoteSideId::Actual(_) => None,
        })
        .collect();

    for (index, annotations) in &actual_diverged_annotations {
        if diverged_actual_deleted.contains(index) {
            continue;
        }
        let mut chosen: Option<Annotation> = None;
        for annotation in annotations {
            let replace = match &chosen {
                None => true,
                Some(existing) => {
                    annotation.reason_priority() >= existing.reason_priority()
                }
            };
            if replace {
                chosen = Some(annotation.clone());
            }
        }
        if let Some(chosen) = chosen {
            remote_outcomes[*index] = RemoteOutcome::Remain(Some(chosen));
        }
    }

    #[derive(Clone)]
    struct RemainRemoteDisplay {
        name: String,
        annotation: Option<Annotation>,
        remote_name_for_skip: Option<String>,
    }
    let mut remain_remotes: Vec<RemainRemoteDisplay> = Vec::new();
    for (index, remote) in remotes.iter().enumerate() {
        if diverged_actual_deleted.contains(&index) {
            continue;
        }
        if let RemoteOutcome::Remain(annotation) = &remote_outcomes[index] {
            remain_remotes.push(RemainRemoteDisplay {
                name: remote.shorthand.clone(),
                annotation: annotation.clone(),
                remote_name_for_skip: Some(remote.remote_name.clone()),
            });
        }
    }
    for (index, pseudo) in pseudos.iter().enumerate() {
        if diverged_pseudo_deleted.contains(&index) {
            continue;
        }
        if let Some(annotations) = pseudo_diverged_annotations.get(&index) {
            let mut chosen: Option<Annotation> = None;
            for annotation in annotations {
                let replace = match &chosen {
                    None => true,
                    Some(existing) => {
                        annotation.reason_priority() >= existing.reason_priority()
                    }
                };
                if replace {
                    chosen = Some(annotation.clone());
                }
            }
            remain_remotes.push(RemainRemoteDisplay {
                name: pseudo.display_name.clone(),
                annotation: chosen,
                remote_name_for_skip: None,
            });
        }
    }

    let mut merged_local_items: Vec<String> = Vec::new();
    let mut stray_local_items: Vec<String> = Vec::new();
    for (local, outcome) in locals.iter().zip(&local_outcomes) {
        match outcome {
            LocalOutcome::DeleteMerged => {
                if local.upstream_refname.is_none() {
                    merged_local_items
                        .push(format!("{} (non-tracking)", local.shorthand));
                } else {
                    merged_local_items.push(local.shorthand.clone());
                }
            }
            LocalOutcome::DeleteStray => stray_local_items.push(local.shorthand.clone()),
            LocalOutcome::Remain(_) => {}
        }
    }

    let mut merged_remote_items: Vec<(String, String, String)> = Vec::new();
    for (remote, outcome) in remotes.iter().zip(&remote_outcomes) {
        if let RemoteOutcome::DeleteMerged { non_upstream } = outcome {
            let mut display = format!("{}, {}", remote.remote_name, remote.merge_ref);
            if *non_upstream {
                display.push_str(" (non-upstream)");
            }
            merged_remote_items.push((
                display,
                remote.remote_name.clone(),
                remote.merge_ref.clone(),
            ));
        }
    }

    println!("Branches that will remain:");
    println!("  local branches:");
    let mut has_skip_1 = false;
    let mut has_skip_2 = false;
    for (local, outcome) in locals.iter().zip(&local_outcomes) {
        if let LocalOutcome::Remain(annotation) = outcome {
            let suffix = annotation
                .as_ref()
                .map(|annotation| annotation.suffix())
                .unwrap_or_default();
            match annotation {
                Some(Annotation::Skipped(1)) => has_skip_1 = true,
                Some(Annotation::Skipped(2)) => has_skip_2 = true,
                _ => {}
            }
            println!("    {}{}", local.shorthand, suffix);
        }
    }
    println!("  remote references:");
    let mut skip_3_count = 0usize;
    let mut skip_3_remote: Option<String> = None;
    for remain in &remain_remotes {
        let suffix = remain
            .annotation
            .as_ref()
            .map(|annotation| annotation.suffix())
            .unwrap_or_default();
        match &remain.annotation {
            Some(Annotation::Skipped(1)) => has_skip_1 = true,
            Some(Annotation::Skipped(2)) => has_skip_2 = true,
            Some(Annotation::Skipped(3)) => {
                skip_3_count += 1;
                skip_3_remote = remain.remote_name_for_skip.clone();
            }
            _ => {}
        }
        println!("    {}{}", remain.name, suffix);
    }
    if has_skip_1 || has_skip_2 || skip_3_count > 0 {
        println!("  Some branches are skipped. Consider following to scan them:");
        if has_skip_1 {
            println!("    *1: Add `--delete 'merged:*'` flag.");
        }
        if has_skip_2 {
            println!(
                "    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag."
            );
        }
        if skip_3_count > 0 {
            let scope = if skip_3_count == 1 {
                skip_3_remote.as_deref().unwrap_or("*")
            } else {
                "*"
            };
            println!(
                "    *3: Make it upstream of a tracking branch or add `--delete 'remote:{}'` flag.",
                scope
            );
        }
    }
    println!();

    let has_candidates = !merged_local_items.is_empty()
        || !merged_remote_items.is_empty()
        || !stray_local_items.is_empty()
        || !diverged_remote_items.is_empty();

    if !merged_local_items.is_empty() {
        println!("Delete merged local branches:");
        for item in &merged_local_items {
            println!("  - {}", item);
        }
    }
    if !merged_remote_items.is_empty() {
        println!("Delete merged remote refs:");
        for (display, _, _) in &merged_remote_items {
            println!("  - {}", display);
        }
    }
    if !stray_local_items.is_empty() {
        println!("Delete stray local branches:");
        for item in &stray_local_items {
            println!("  - {}", item);
        }
    }
    if !diverged_remote_items.is_empty() {
        println!("Delete diverged remote refs:");
        for item in &diverged_remote_items {
            println!("  - {}, {}", item.remote_name, item.merge_ref);
        }
    }

    let mut perform_deletions = has_candidates;
    if has_candidates && !dry_run && resolved.confirm {
        if !prompt_confirm()? {
            println!("Cancelled");
            perform_deletions = false;
        }
    }

    if perform_deletions {
        let mut remote_delete_execution: Vec<(String, String)> = Vec::new();
        for (_, remote_name, merge_ref) in &merged_remote_items {
            remote_delete_execution.push((remote_name.clone(), merge_ref.clone()));
        }
        for item in &diverged_remote_items {
            remote_delete_execution
                .push((item.remote_name.clone(), item.merge_ref.clone()));
        }

        let mut grouped_remote_deletes: Vec<(String, Vec<String>)> = Vec::new();
        for (remote_name, merge_ref) in remote_delete_execution {
            if let Some((_, refs)) = grouped_remote_deletes
                .iter_mut()
                .find(|(name, _)| name == &remote_name)
            {
                refs.push(merge_ref);
            } else {
                grouped_remote_deletes.push((remote_name, vec![merge_ref]));
            }
        }

        for (remote_name, merge_refs) in &grouped_remote_deletes {
            let mut args: Vec<String> = Vec::new();
            args.push("push".to_string());
            if dry_run {
                args.push("--dry-run".to_string());
            }
            args.push(remote_name.clone());
            for merge_ref in merge_refs {
                args.push(format!(":{}", merge_ref));
            }
            let arg_refs: Vec<&str> = args.iter().map(|arg| arg.as_str()).collect();
            run_git_inherit(&workdir, &arg_refs)?;
        }

        let local_delete_names: HashSet<String> = locals
            .iter()
            .zip(&local_outcomes)
            .filter_map(|(local, outcome)| match outcome {
                LocalOutcome::DeleteMerged | LocalOutcome::DeleteStray => {
                    Some(local.shorthand.clone())
                }
                LocalOutcome::Remain(_) => None,
            })
            .collect();

        if let Some(current_ref) = &current_head_ref {
            if let Some(current_local) = locals
                .iter()
                .find(|local| &local.refname == current_ref)
            {
                if local_delete_names.contains(&current_local.shorthand) {
                    if dry_run {
                        let commit = checker.commit_for_ref(&current_local.refname)?;
                        let short_id = commit.id().to_string();
                        println!(
                            "Note: switching to '{}' (dry run)",
                            current_local.refname
                        );
                        println!("You are in 'detached HED' state... blah blah...");
                        println!(
                            "HEAD is now at {} {} (dry run)",
                            &short_id[..7],
                            commit.summary().unwrap_or("")
                        );
                    } else {
                        run_git_inherit(
                            &workdir,
                            &["checkout", &current_local.refname],
                        )?;
                    }
                }
            }
        }

        for name in local_delete_names {
            if dry_run {
                println!("Delete branch {} (dry run).", name);
            } else {
                run_git_inherit(&workdir, &["branch", "-D", &name])?;
            }
        }
    }

    if matches!(resolved.bases_input, BasesInput::Default) && resolved.update {
        check_remote_heads(&repo, &workdir)?;
    }

    Ok(())
}

fn main() -> Result<()> {
    let cli = parse_cli();
    run(cli)
}
