fn status_io_error(status: std::process::ExitStatus) -> io::Error {
    io::Error::from_raw_os_error(status.code().unwrap_or(1))
}

fn run_git_inherit(workdir: &Path, args: &[&str]) -> Result<()> {
    let status = ProcessCommand::new("git")
        .arg("-C")
        .arg(workdir)
        .args(args)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()?;
    if status.success() {
        Ok(())
    } else {
        Err(status_io_error(status).into())
    }
}

fn run_git_capture(workdir: &Path, args: &[&str]) -> Result<String> {
    let output = ProcessCommand::new("git")
        .arg("-C")
        .arg(workdir)
        .args(args)
        .output()?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).into_owned())
    } else {
        Err(status_io_error(output.status).into())
    }
}

#[derive(Default)]
struct Bases {
    local_refs: HashSet<String>,
    remote_refs: HashSet<String>,
    remote_ref_list: Vec<String>,
    direct_remote_tokens: HashMap<String, String>,
}

impl Bases {
    fn add_remote(&mut self, refname: String) {
        if self.remote_refs.insert(refname.clone()) {
            self.remote_ref_list.push(refname);
        }
    }
}

fn remote_head_targets(repo: &Repository) -> Vec<String> {
    let mut targets = Vec::new();
    if let Ok(mut references) = repo.references_glob("refs/remotes/*/HEAD") {
        while let Some(reference) = references.next() {
            let Ok(reference) = reference else {
                continue;
            };
            if let Ok(resolved) = reference.resolve() {
                if let Ok(Some(name)) = resolved.name() {
                    let name = name.to_string();
                    if !targets.contains(&name) {
                        targets.push(name);
                    }
                }
            }
        }
    }
    targets
}

fn canonicalize_bases(repo: &Repository, input: &BasesInput) -> Result<Bases> {
    let mut bases = Bases::default();
    match input {
        BasesInput::Default => {
            let targets = remote_head_targets(repo);
            for target in &targets {
                bases.add_remote(target.clone());
            }
            let target_set: HashSet<&str> = targets.iter().map(|s| s.as_str()).collect();
            for branch in repo.branches(Some(BranchType::Local))? {
                let (branch, _) = branch?;
                let Some(refname) = branch.get().name().ok().flatten().map(|s| s.to_string())
                else {
                    continue;
                };
                if let Ok(upstream_name) = repo.branch_upstream_name(&refname) {
                    if let Ok(upstream_name) = upstream_name.as_str() {
                        if target_set.contains(upstream_name) {
                            bases.local_refs.insert(refname);
                        }
                    }
                }
            }
        }
        BasesInput::Explicit(tokens) => {
            for token in tokens {
                // libgit2 releases used by the reference program did not
                // resolve a lone "@" as HEAD.
                if token == "@" {
                    continue;
                }
                let reference = match repo.resolve_reference_from_short_name(token) {
                    Ok(reference) => reference,
                    Err(e) if e.code() == ErrorCode::NotFound => continue,
                    Err(e) => return Err(e.into()),
                };
                let resolved = reference.resolve()?;
                let refname = resolved
                    .name()
                    .ok()
                    .flatten()
                    .map(|name| name.to_string());
                if resolved.is_branch() {
                    let branch = git2::Branch::wrap(resolved);
                    if let Ok(upstream) = branch.upstream() {
                        if upstream.get().is_remote() {
                            if let Some(local_refname) = refname {
                                bases.local_refs.insert(local_refname);
                            }
                            if let Ok(Some(upstream_refname)) = upstream.get().name() {
                                bases.add_remote(upstream_refname.to_string());
                            }
                        }
                    }
                } else if resolved.is_remote() {
                    if let Some(remote_refname) = refname {
                        bases
                            .direct_remote_tokens
                            .entry(remote_refname.clone())
                            .or_insert_with(|| token.clone());
                        bases.add_remote(remote_refname);
                    }
                } else {
                    bail!("Reference {:?} is not a branch", resolved.name().ok().flatten());
                }
            }
        }
    }
    Ok(bases)
}

