import pty, os, select, time, sys, subprocess, pathlib, shutil

def restore():
    shutil.rmtree('/tmp/t',ignore_errors=True); subprocess.run(['tar','-xpf','/tmp/snap.tar','-C','/tmp'],check=True)
def state():
    env=dict(os.environ,HOME='/tmp/t/home',GIT_CONFIG_NOSYSTEM='1')
    p=subprocess.run(['git','branch','-avv'],cwd='/tmp/t/work',env=env,capture_output=True,text=True); q=subprocess.run(['git','branch','-avv'],cwd='/tmp/t/remote.git',env=env,capture_output=True,text=True); return p.stdout+q.stdout

def one(binary,args,key):
    restore()
    pid,fd=pty.fork()
    if pid==0:
        os.chdir('/tmp/t/work'); os.environ.update(HOME='/tmp/t/home',TERM='xterm-256color',GIT_CONFIG_NOSYSTEM='1'); os.execv(binary,['executable']+args)
