new='''const GROUP_USAGE: &str =
    "<--bases <BASES>|--protected <PROTECTED>|--no-update|--update|--update-interval <UPDATE_INTERVAL>|--no-confirm|--confirm|--no-detach|--detach|--delete <DELETE>|--dry-run>";

fn has_hidden_group_flag_before(invalid: &str) -> bool {
    let mut pending_value = false;
    for arg in std::env::args_os().skip(1) {
        let token = arg.to_string_lossy().into_owned();
        if token == "--" {
            return false;
        }
        if token == invalid || token.starts_with(&format!("{}=", invalid)) {
            return false;
        }
        if pending_value {
            pending_value = false;
            continue;
        }
        if matches!(
            token.as_str(),
            "--update" | "--confirm" | "--detach"
        ) {
            return true;
        }
        if matches!(
            token.as_str(),
            "--bases"
                | "--base"
                | "--protected"
                | "--delete"
                | "--update-interval"
                | "-b"
                | "-p"
                | "-d"
        ) {
            pending_value = true;
        }
    }
    false
}

fn rewrite_group_usage(err: &mut clap::Error) {
    if err.kind() != ErrorKind::UnknownArgument {
        return;
    }
    let invalid = match err.get(ContextKind::InvalidArg) {
        Some(ContextValue::String(value)) => value.clone(),
        _ => return,
    };
    if !invalid.starts_with("--") || invalid.len() <= 2 {
        return;
    }
    let suggested = match err.get(ContextKind::SuggestedArg) {
        Some(ContextValue::String(value)) => Some(value.clone()),
        _ => None,
    };
    let usage_plain = match err.get(ContextKind::Usage) {
        Some(ContextValue::StyledStr(styled)) => styled.to_string(),
        Some(ContextValue::String(value)) => value.clone(),
        _ => return,
    };
    let bin = usage_plain
        .split_whitespace()
        .next()
        .unwrap_or("executable")
        .to_string();
    let custom_longs = [
        "--bases",
        "--base",
        "--protected",
        "--no-update",
        "--update",
        "--update-interval",
        "--no-confirm",
        "--confirm",
        "--no-detach",
        "--detach",
        "--delete",
        "--dry-run",
    ];
    let usage_has_custom = usage_plain
        .split_whitespace()
        .any(|token| custom_longs.contains(&token));
    let suggested_is_builtin = matches!(
        suggested.as_deref(),
        Some("--help") | Some("--version")
    );
    let suggested_is_custom = suggested
        .as_deref()
        .map(|value| custom_longs.contains(&value))
        .unwrap_or(false);
    let group_needed = suggested_is_custom
        || usage_has_custom
        || has_hidden_group_flag_before(&invalid);
    if !group_needed {
        return;
    }
    let mut styled = StyledStr::new();
    styled.push_str(&format!("\\u{{1b}}[1m{}\\u{{1b}}[0m ", bin));
    if suggested_is_builtin {
        if let Some(suggested) = &suggested {
            styled.push_str(&format!("\\u{{1b}}[1m{}\\u{{1b}}[0m ", suggested));
        }
    }
    styled.push_str(GROUP_USAGE);
    err.insert(
        ContextKind::Usage,
        ContextValue::StyledStr(styled),
    );
}

fn parse_cli() -> CliOptions {
    let mut command = build_command();
    let matches = match command.try_get_matches_from_mut(std::env::args_os()) {
        Ok(matches) => matches,
        Err(mut err) => {
            rewrite_group_usage(&mut err);
            err.exit();
        }
    };'''
