            let Ok(reference) = reference else {
                continue;
            };
            let Ok(local_resolved) = reference.resolve() else {
                continue;
            };
            let Ok(local_resolved_name) = local_resolved.name() else {
                continue;
            };
            let refname = local_resolved_name;
            assert!(refname.starts_with("refs/remotes/"));
            let target_remote = match repo.branch_remote_name(refname) {
                Ok(buf) => buf.as_str()?.to_string(),
                Err(_) => bail!("remote with matching refspec not found"),
            };
            let local_branch_ref =
                remote_merge_ref(repo, &target_remote, refname);
            let Some(server_ref) = server_heads.get(&target_remote) else {
                continue;
            };
            if server_ref != &local_branch_ref {
                out_of_sync.push((
                    target_remote,
                    local_branch_ref,
                    server_ref.clone(),
                ));
            }
        }
    }

