    ) -> Result<HashSet<String>> {
        if let Some(cached) = self.git_base_patchid_sets.get(&(tip, hide)) {
            return Ok(cached.clone());
        }
        let mut walk = self.repo.revwalk()?;
        walk.push(tip)?;
        walk.hide(hide)?;
        let mut oids = Vec::new();
        for oid in walk {
            let oid = oid?;
            let commit = self.repo.find_commit(oid)?;
            if commit.parent_count() == 1 {
                oids.push(oid);
            }
        }
        let mut set = HashSet::new();
        for oid in oids {
            if let Some(patchid) = self.git_commit_patchid(oid)? {
                set.insert(patchid);
            }
        }
        self.git_base_patchid_sets.insert((tip, hide), set.clone());
        Ok(set)
    }

