        let Some(git_squash_patchid) = self.git_patch_id(&[
            "diff",
            "--full-index",
            &merge_base.to_string(),
            &branch_commit.id().to_string(),
        ])?
        else {
            return Ok(false);
        };
        let git_base_patchids =
            self.git_patchid_set_between(base_commit.id(), merge_base)?;
        Ok(git_base_patchids.contains(&git_squash_patchid))'''
